static char *parse_to_param(char *const buffer, const char *const end,
                struct to_body *const to_b, const int allow_comma_sep,
                int *const returned_status)
{
        struct to_param *param;
        struct to_param *newparam;
        int status;
        int saved_status;
        char *tmp;

        param = 0;
        newparam = 0;
        status = E_PARA_VALUE;
        saved_status = E_PARA_VALUE;
        for(tmp = buffer; tmp < end; tmp++) {
                switch(*tmp) {
                        case ' ':
                        case '\t':
                                switch(status) {
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                status = S_EQUAL;
                                                break;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                                status = E_PARA_VALUE;
                                                add_param(param, to_b, newparam);
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now =' '*/
                                                status = saved_status;
                                                break;
                                }
                                break;
                        case '\n':
                                switch(status) {
                                        case S_PARA_NAME:
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                        case E_PARA_VALUE:
                                                saved_status = status;
                                                status = F_LF;
                                                break;
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                saved_status = S_EQUAL;
                                                status = F_LF;
                                                break;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                                saved_status = E_PARA_VALUE;
                                                status = F_LF;
                                                add_param(param, to_b, newparam);
                                                break;
                                        case F_CR:
                                                status = F_CRLF;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                                status = saved_status;
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case '\r':
                                switch(status) {
                                        case S_PARA_NAME:
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                        case E_PARA_VALUE:
                                                saved_status = status;
                                                status = F_CR;
                                                break;
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                saved_status = S_EQUAL;
                                                status = F_CR;
                                                break;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                                saved_status = E_PARA_VALUE;
                                                status = F_CR;
                                                add_param(param, to_b, newparam);
                                                break;
                                        case F_CRLF:
                                        case F_CR:
                                        case F_LF:
                                                status = saved_status;
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case 0:
                                switch(status) {
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                status = S_EQUAL;
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                                saved_status = status;
                                                goto endofheader;
                                        case PARA_VALUE_TOKEN:
                                                status = E_PARA_VALUE;
                                                param->value.len = tmp - param->value.s;
                                                add_param(param, to_b, newparam);
                                        case E_PARA_VALUE:
                                                saved_status = status;
                                                goto endofheader;
                                                break;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case '\\':
                                switch(status) {
                                        case PARA_VALUE_QUOTED:
                                                switch(*(tmp + 1)) {
                                                        case '\r':
                                                        case '\n':
                                                                break;
                                                        default:
                                                                tmp++;
                                                }
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case '"':
                                switch(status) {
                                        case S_PARA_VALUE:
                                                param->value.s = tmp + 1;
                                                status = PARA_VALUE_QUOTED;
                                                break;
                                        case PARA_VALUE_QUOTED:
                                                param->value.len = tmp - param->value.s;
                                                add_param(param, to_b, newparam);
                                                status = E_PARA_VALUE;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case ';':
                                switch(status) {
                                        case PARA_VALUE_QUOTED:
                                                break;
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                        case S_EQUAL:
                                                param->value.s = 0;
                                                param->value.len = 0;
                                                goto semicolon_add_param;
                                        case S_PARA_VALUE:
                                                param->value.s = tmp;
                                        case PARA_VALUE_TOKEN:
                                                param->value.len = tmp - param->value.s;
                                        semicolon_add_param:
                                                add_param(param, to_b, newparam);
                                        case E_PARA_VALUE:
